def decide(recipient_reputation, round_num, my_history):
    # Only use round number and own past cooperation count (not partner actions).
    # Compute fraction of rounds where we cooperated.
    if len(my_history) > 0:
        own_coop = sum(1 for (my_act, _) in my_history if my_act == 'cooperate')
        coop_fraction = own_coop / len(my_history)
    else:
        coop_fraction = 0.5  # neutral start

    # Threshold decreases with round (more trusting over time) and increases
    # if we have been cooperative (rewarding our own consistency).
    threshold = 0.4 - 0.2 * (round_num / 10.0) - 0.2 * coop_fraction
    threshold = max(0.0, min(1.0, threshold))

    return recipient_reputation > threshold

